// Boss fight: fire constantly, orbit at 5-9 m (flip direction every 40 ticks), jump telegraphed shockwaves, back off when close. Elsewhere: brisk walk, ladder/lift/stuck logic, hop the crane steps.
function step(o, m) {
  const g = o.goal;
  m.n = (m.n || 0) + 1;
  const stuck = stuckTicks(o, m, 30);
  if (o.carried) return { turn: 0, move: 0, fire: false, jump: true };
  if (o.hang) return { turn: 0, move: 0, fire: false, jump: m.n % 2 === 0 };
  if (o.rider) return { turn: m.n % 4 < 2 ? -1 : 1, move: 0, fire: false, jump: m.n % 2 === 0 };

  const boss = o.foes.find(f => f.k === 'boss' && f.awake);
  const useNow = o.inv.length > 0 && m.n - (m.u || -99) > 25;
  if (boss && boss.d < 16) {
    if (useNow) m.u = m.n;
    if (m.n % 40 === 0) m.s = -(m.s || 1);
    const s = m.s || 1;
    const wind = /slam|wind|crouch|rev|shock|stomp|dive/.test(boss.st || '');
    let mv = boss.d > 9 ? 0.8 : boss.d < 5 ? -0.6 : 0.4;
    if (Math.abs(boss.b) > 1.2) mv = 0;      // turn to face it first
    if (mv > 0 && o.drop.f < 2) mv = 0;      // don't walk off the edge
    const off = boss.d < 7 ? 0.3 * s : 0;    // sidestep angle while close = orbit
    return {
      turn: steerTo(boss.b + off, 2.5),
      move: clampU(mv),
      fire: true,
      jump: (wind && boss.d < 9) || shotDanger(o, 3, 0.6) || telegraphed(o, 5),
      use: useNow,
      sel: 0,
    };
  }

  const near = o.foes.some(f => f.awake && f.d < 8);
  const fire = !!o.aim.hit || (m.n % 3 !== 0 && near);
  const e = wrapA(Math.PI - o.yaw);
  if (g.kind === 'ladder' || (g.kind === 'ladder-approach' && g.d < 2)) {
    return { turn: clampU(e * 3), move: Math.abs(e) < 0.5 ? 1 : 0, fire, jump: false };
  }
  if (g.kind === 'lift' && g.d < 1.2) return { turn: steerTo(g.b, 2), move: 0, fire, jump: false };

  if (stuck && !(m.esc > 0) && g.kind !== 'lift') { m.esc = 15; m.dir = -(m.dir || 1); m.c = -30; }
  const edge = ledgeAhead(o, g);
  if (m.esc > 0) {
    m.esc--;
    return {
      turn: clampU(m.dir * 0.8),
      move: m.esc > 8 ? -0.7 : edge ? 0 : 0.7,
      fire,
      jump: m.esc % 4 === 0 && o.ground,
    };
  }

  const hop = (g.kind === 'crane-step' && g.d < 1.5 && o.ground) || telegraphed(o, 5) || shotDanger(o, 3, 0.6);
  const slow = o.foes.some(f => f.awake && f.d < 2.5);
  const brisk = Math.abs(g.b) < 1.6;
  return {
    turn: clampU(g.b * 2.5),
    move: edge ? 0 : brisk ? (slow ? 0.6 : 1) : 0.5,
    fire,
    jump: hop,
  };
}

// Spray and slow: fire on ~3 of 4 ticks when a foe is near (always during the boss fight); walk at about a third speed; heal earlier
function step(o, m) {
  const g = o.goal;
  m.n = (m.n || 0) + 1;
  if (o.carried) return { turn: 0, move: 0, fire: false, jump: true };
  if (o.hang) return { turn: 0, move: 0, fire: false, jump: m.n % 2 === 0 };
  if (o.rider) return { turn: m.n % 4 < 2 ? -1 : 1, move: 0, fire: false, jump: m.n % 2 === 0 };

  const stuck = stuckTicks(o, m, 20);
  const boss = o.foes.find(f => f.k === 'boss' && f.awake);
  const near = o.foes.some(f => f.awake && f.d < 12);
  const fire = (!!o.aim.hit || near) && (!!boss || m.n % 3 !== 0);
  const slam = o.foes.some(f => /slam|windup|rev|dive|shock/.test(f.st || '') && f.d < 4.5) || shotDanger(o, 3, 0.5);
  const out = (turn, move, jump, use) => ({
    turn: clampU(turn), move: clampU(move), fire, jump: !!jump, use: !!use, sel: 0,
  });

  if (boss && boss.d < 14) {
    const ang = Math.atan2(boss.dy, boss.d);
    const useNow = o.inv.length > 0 && m.n - (m.u || -99) > 25;
    if (useNow) m.u = m.n;
    // orbit: at 6-10 m, aim 0.5 rad off the wolf and flip the arc every 2.5 s, so we circle it while firing
    const arc = Math.floor(m.n / 25) % 2 ? 0.5 : -0.5;
    let move = boss.d > 10 ? 0.8 : boss.d < 6 ? -0.6 : 0.5;
    if (!boss.band && Math.abs(ang) > 0.15 && boss.d < 12) move = -0.6;
    if (move > 0 && o.drop.f < 2) move = 0;
    const turn = steerTo(boss.b + (boss.d > 6 && boss.d < 10 ? arc : 0), 2.5);
    // jump any telegraphed slam, shockwave, dive or brick; keep the trigger held the whole fight
    return { turn, move: clampU(move), fire: true, jump: telegraphed(o, 9) && !!o.ground, use: useNow, sel: 0 };
  }

  const e = wrapA(Math.PI - o.yaw);
  if (g.kind === 'ladder' || (g.kind === 'ladder-approach' && g.d < 2.5)) {
    if (g.kind === 'ladder-approach' && Math.abs(e) > 0.5 && g.d > 1) {
      return out(steerTo(g.b, 2.5), Math.abs(g.b) < 1 ? 0.5 : 0, slam);
    }
    return out(e * 3, Math.abs(e) < 0.5 ? 1 : 0, slam);
  }
  if (g.kind === 'lift' && g.d < 1.2) return out(steerTo(g.b, 2), 0, slam);

  const ramp = /stairs|spring|crane/.test(g.kind);
  if (stuck) {
    if (/stairs|crane/.test(g.kind)) return out(steerTo(g.b, 2.5), Math.abs(g.b) < 1 ? 1 : 0.3, m.n % 6 < 3);
    return out(Math.sin(m.n * 0.7), o.drop.f < 1.5 ? 0 : 0.8, true);
  }

  const heal = o.hp < 70 ? o.items.find(i => i.k === 'juice' && i.d < 10) : null;
  const tb = heal ? heal.b : g.b;
  const edge = !ramp && o.drop.f < 1.5;
  const hop = g.kind === 'crane-step' && g.d < 1.5 && o.ground;
  const move = edge || Math.abs(tb) >= 1.4 ? 0 : Math.abs(tb) < 0.9 ? 0.9 : 0.6;
  return out(steerTo(tb, 2.5), move, hop || slam);
}

